const e="etats-unis",l=1,s={habitants:"les Américains",adjectif:"américain",adjectifF:"américaine",devise:"In Gridlock We Trust : tout est possible, sous réserve de soixante voix.",medaillon:"US",chaineInfo:"US LIBERTY NEWS",hymne:"Que Dieu bénisse l’Amérique, et surtout son calendrier budgétaire"},n={chambre:"Congrès",chambreLong:"Congrès des États-Unis",chefGouvernement:"Président des États-Unis (chef de l’exécutif)",chefEtat:"Président des États-Unis",passageForce:{label:"Décret présidentiel",description:"Le président signe un décret et s’exonère du vote du Congrès. Les tribunaux fédéraux examineront la légalité dans quelques années, quand plus personne ne se souviendra de la question.",news:"Décret présidentiel : « {loi} » entre en vigueur, les juges sortent leurs codes"},censure:{label:"Mise en accusation",description:"La Chambre vote un acte d’accusation et le Sénat le juge, avec la solennité d’un procès et la durée d’une saison de série. Il faut ensuite deux tiers du Sénat pour condamner, soit un consensus aussi rare qu’un été sans orage.",news:"Mise en accusation : le Congrès s’offre une saison de procès"},dissolution:{label:"Appel direct au peuple",description:"Le président prend l’opinion à témoin, convoque une tournée de meetings et menace de faire campagne contre le Congrès. Rien n’est dissous, mais tout le monde a peur.",news:"Le président appelle le peuple à trancher, le Congrès redécouvre les sondages"}},t={type:"presidentielle",label:"Élection présidentielle",intro:"Cinquante États, des centaines de millions en publicité et un collège de grands électeurs que personne n’a jamais pu expliquer en moins de neuf minutes. Les États pivots sont déjà saturés de spots.",adversaires:[{id:"hollis-brand",name:"Gordon Hollis-Brand",parti:"Parti de la Liberté Républicaine",style:"attaque",punchlines:["Mon adversaire parle de fermeture du gouvernement, je parle de fermeture de mon agenda pour les Américains.","On a déjà vu ce film : un plafond de la dette, un shutdown, et un communiqué de regret.","Elle promet de réparer les ponts. Moi, je promets d’en construire un devant chez vous."],genre:"m"},{id:"marisol-vance",name:"Marisol Vance-Ortega",parti:"Union Démocrate du Progrès",style:"emotion",punchlines:["Dans chaque comté, j’ai rencontré des gens qui ne demandent qu’un peu de respect et un peu moins de factures.","On ne gouverne pas par décret, on gouverne en se regardant dans les yeux. Et en votant un budget.","Je ne suis pas là pour diviser, je suis là pour que la division soit moins chère."],genre:"f"},{id:"dale-crossway",name:"Dale Crossway",parti:"Indépendants du Grand Centre",style:"esquive",punchlines:["Je ne suis ni de l’un ni de l’autre, ce qui me rend disponible pour les deux.","Les extrêmes crient, moi je murmure, donc on m’entend moins, mais c’est reposant.","Mon programme tient sur une serviette en papier, ce qui est déjà un progrès par rapport aux autres."],genre:"m"}],nuitElectorale:"Les cartes des États virent au rouge, au bleu et au « trop serré pour conclure ». À minuit, la Pennsylvanie compte encore, et elle comptera jusqu’au lendemain."},a=[{id:"etats-unis-assurance-sante-publique",title:"Option publique d’assurance santé",domain:"sante",description:"Une assurance publique en concurrence avec les assureurs privés. Chacun garde « le choix », c’est-à-dire quarante-trois formulaires au lieu de quarante-quatre.",accroche:"Une option publique, à côté de cinquante options privées et d'une notice de mille pages.",effects:{cohesion:5,pouvoirAchat:3,budget:-6,popularite:-1},delayed:[{delay:3,effects:{cohesion:2,popularite:2},label:"Moins de faillites dues aux factures médicales"}],groupStance:{"republicains-libres":-.9,"democrates-union":.8,"caucus-ruraux":-.2,"progressistes-ouest":.9,"independants-centre":.1,libertariens:-1},streetAnger:.6},{id:"etats-unis-plafond-dette-pacte",title:"Pacte de relèvement du plafond de la dette",domain:"institutions",description:"Relever le plafond de la dette à la dernière minute, comme chaque année. Le suspense est budgété, la fin ne l’est jamais.",accroche:"Le plafond monte encore, et la nation lève les yeux avec un certain respect.",effects:{economie:4,international:3,assemblee:-3,budget:-3},delayed:[{delay:3,effects:{budget:-2,assemblee:-2},label:"Contreparties exigées en coulisses"}],groupStance:{"republicains-libres":.1,"democrates-union":.3,"caucus-ruraux":.4,"progressistes-ouest":-.2,"independants-centre":.6,libertariens:-.9},streetAnger:.2},{id:"etats-unis-frontiere-infrastructures",title:"Plan routes, ponts et tunnels",domain:"ecologie",description:"Réparer enfin les ponts avant qu’ils ne fassent la une. Chaque circonscription exige son pont, y compris celles qui n’ont pas de rivière.",accroche:"Des ponts solides pour traverser les fleuves, et des débats pour traverser les ponts.",effects:{economie:4,cohesion:2,budget:-6,ecologie:-1},delayed:[{delay:3,effects:{economie:3,pouvoirAchat:1},label:"Chantiers en cours, embouteillages en prime"},{delay:4,effects:{popularite:2},label:"Inaugurations en série"}],groupStance:{"republicains-libres":.3,"democrates-union":.6,"caucus-ruraux":.7,"progressistes-ouest":.2,"independants-centre":.6,libertariens:-.7},streetAnger:.1},{id:"etats-unis-permis-armes-verification",title:"Vérification universelle avant achat d’arme",domain:"securite",description:"Un contrôle d’antécédents pour toute vente d’arme. Le texte tient en trois pages, les commentaires en trois mille.",accroche:"Une vérification avant l'achat, juste le temps de lire l'étiquette en entier.",effects:{securite:5,cohesion:2,popularite:-3,assemblee:-3},delayed:[{delay:3,effects:{securite:2,cohesion:1},label:"Moins de ventes sans contrôle"}],groupStance:{"republicains-libres":-.9,"democrates-union":.7,"caucus-ruraux":-.8,"progressistes-ouest":.8,"independants-centre":.2,libertariens:-1},streetAnger:.7},{id:"etats-unis-tarifs-douaniers-acier",title:"Droits de douane sur l’acier et l’aluminium",domain:"travail",description:"Protéger les aciéries de l’Ohio en taxant celles des autres. Les consommateurs financent la fierté industrielle au prix du boulon.",accroche:"L'acier se protège avec de l'acier, et la facture finit sur l'étagère du voisin.",effects:{economie:3,pouvoirAchat:-4,international:-4,popularite:1},delayed:[{delay:3,effects:{pouvoirAchat:-2,international:-2},label:"Mesures de rétorsion commerciales"},{delay:4,effects:{economie:2},label:"Embauches dans les aciéries"}],groupStance:{"republicains-libres":.6,"democrates-union":-.4,"caucus-ruraux":.6,"progressistes-ouest":-.5,"independants-centre":.1,libertariens:-1},streetAnger:.3},{id:"etats-unis-dette-etudiante",title:"Allègement de la dette étudiante",domain:"education",description:"Effacer une partie des prêts universitaires. Les diplômés applaudissent, les plombiers demandent si leur camionnette compte comme un cursus.",accroche:"Les diplômés respirent, les banquiers soupirent, et l'amphithéâtre applaudit à moitié.",effects:{pouvoirAchat:4,popularite:3,budget:-7,cohesion:-2},delayed:[{delay:3,effects:{budget:-2,pouvoirAchat:1},label:"Facture pour le Trésor"}],groupStance:{"republicains-libres":-.8,"democrates-union":.7,"caucus-ruraux":-.6,"progressistes-ouest":.8,"independants-centre":-.1,libertariens:-.9},streetAnger:.4},{id:"etats-unis-permis-forage-federal",title:"Permis de forage sur terres fédérales",domain:"energie",description:"Ouvrir des terres fédérales à l’extraction. Les cartes du ministère de l’Intérieur ont dû être imprimées en plus grand pour y loger les concessions.",accroche:"Forer partout, sauf dans le jardin de la sénatrice qui préside la commission.",effects:{economie:4,budget:3,ecologie:-6,popularite:-1},delayed:[{delay:3,effects:{economie:2,budget:2},label:"Redevances encaissées"},{delay:4,effects:{ecologie:-2},label:"Marées noires et procès"}],groupStance:{"republicains-libres":.9,"democrates-union":-.6,"caucus-ruraux":.7,"progressistes-ouest":-.9,"independants-centre":.1,libertariens:.6},streetAnger:.5},{id:"etats-unis-veto-surmontable",title:"Réforme du veto et des lois fourre-tout",domain:"institutions",description:"Interdire les amendements sans rapport avec le texte. Fini le budget qui finance un pont, un musée de la moutarde et une base militaire en Alaska.",accroche:"Les lois fourre-tout seront triées, la tombola d'amendements retirée du programme.",effects:{assemblee:-5,cohesion:3,popularite:2},delayed:[{delay:4,effects:{assemblee:2,economie:1},label:"Textes plus lisibles, élus plus grincheux"}],groupStance:{"republicains-libres":-.3,"democrates-union":.3,"caucus-ruraux":-.5,"progressistes-ouest":.4,"independants-centre":.7,libertariens:.3},streetAnger:.1},{id:"etats-unis-agriculture-subventions",title:"Loi agricole quinquennale",domain:"agriculture",description:"Cinq ans de subventions pour le maïs, le soja et la bonne humeur des États ruraux. Les villes sont invitées à ne pas poser de questions sur le sirop de maïs.",accroche:"Les subventions reviennent tous les cinq ans, fidèles comme une récolte de maïs.",effects:{economie:2,cohesion:2,budget:-5,ecologie:-2,assemblee:3},delayed:[{delay:3,effects:{cohesion:2,popularite:1},label:"Récoltes assurées, électeurs aussi"}],groupStance:{"republicains-libres":.4,"democrates-union":.1,"caucus-ruraux":1,"progressistes-ouest":-.7,"independants-centre":.3,libertariens:-.9},streetAnger:.2},{id:"etats-unis-cyber-protection-donnees",title:"Loi fédérale de protection des données",domain:"numerique",description:"Un seul régime pour les données personnelles, au lieu de cinquante. Les géants du numérique réclament l’uniformité, à condition qu’elle soit la leur.",accroche:"Vos données seront protégées, et vous pourrez enfin cocher autre chose que « accepter ».",effects:{cohesion:3,economie:-2,international:2,popularite:2},delayed:[{delay:3,effects:{international:2,economie:1},label:"Standard repris par les partenaires"}],groupStance:{"republicains-libres":-.2,"democrates-union":.5,"caucus-ruraux":.1,"progressistes-ouest":.6,"independants-centre":.5,libertariens:-.8},streetAnger:.2}],i=JSON.parse('[{"id":"etats-unis-ouragan-cote-est","title":"Ouragan de catégorie 4","category":"climat","description":"Un ouragan remonte la côte avec l’assurance d’un huissier. Les gouverneurs réclament l’état de catastrophe, le Congrès réclame un rapport, le vent réclame la parole.","weight":6,"minTurn":3,"choices":[{"id":"aide-federale","label":"Déclarer la catastrophe et débloquer l’aide fédérale","description":"Mobiliser l’agence fédérale sans attendre le vote.","effects":{"cohesion":4,"popularite":3,"budget":-6,"securite":1},"delayed":[{"delay":3,"effects":{"popularite":-1,"budget":-2},"label":"Contrôle des factures de reconstruction"}],"news":"Ouragan : l’aide fédérale arrive, les sacs de sable aussi"},{"id":"etats-gerent","label":"Laisser les États s’organiser","description":"Rappeler que le fédéralisme sert aussi à ça.","effects":{"budget":2,"popularite":-5,"cohesion":-4,"assemblee":1},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Sinistrés sans nouvelles de leur assurance"}],"news":"Ouragan : Washington « suit la situation avec attention »"},{"id":"visite-terrain","label":"Survoler les dégâts en hélicoptère","description":"Un discours ciré jaune, des promesses, une casquette.","effects":{"popularite":2,"cohesion":1,"budget":-2},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"« Il n’a même pas mouillé ses bottes »"}],"news":"Le président survole le désastre, les caméras aussi"}]},{"id":"etats-unis-shutdown-budgetaire","title":"Fermeture des services fédéraux","category":"politique","description":"Faute de budget voté, les parcs nationaux ferment, les musées rouvrent en version audio et les fonctionnaires apprennent le télétravail non rémunéré. Chaque camp accuse l’autre d’avoir éteint la lumière.","weight":7,"minTurn":3,"conditions":[{"gauge":"assemblee","op":"<","value":50}],"choices":[{"id":"concession","label":"Céder sur le texte pour rouvrir","description":"Accepter les conditions du camp adverse.","effects":{"popularite":-3,"assemblee":3,"economie":2,"budget":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Rancune dans les couloirs du Capitole"}],"news":"Shutdown terminé : tout le monde a perdu, un peu moins que prévu"},{"id":"tenir-bon","label":"Tenir bon devant les caméras","description":"Pointer l’obstruction de l’opposition jusqu’à ce que l’opinion tranche.","effects":{"popularite":-2,"economie":-4,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"popularite":3,"assemblee":2},"label":"L’opinion se retourne contre les bloqueurs"}],"chain":{"crisisId":"etats-unis-shutdown-pourrissement","probability":0.4,"delay":1},"news":"Shutdown : sixième jour, la cantine du Capitole manque de café"},{"id":"decret-minimal","label":"Financer le minimum par décret","description":"Maintenir les services essentiels en tordant les textes.","effects":{"securite":2,"economie":1,"assemblee":-5,"budget":-3},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Contentieux devant la Cour"}],"news":"Services essentiels sauvés par décret, juristes en alerte"}]},{"id":"etats-unis-shutdown-pourrissement","title":"Le shutdown s’éternise","category":"politique","description":"Troisième semaine : les contrôleurs aériens appellent à l’aide, les parcs nationaux accueillent des ours en visite libre. Le pays commence à regarder ses élus comme un bus en panne.","weight":5,"chainOnly":true,"choices":[{"id":"negociation-marathon","label":"Enfermer les chefs de groupe jusqu’à un accord","description":"Une nuit entière avec des sandwichs et des amendements.","effects":{"assemblee":3,"popularite":2,"budget":-4,"economie":2},"news":"Accord de nuit : le shutdown se termine sur un paquet de chips"},{"id":"appel-opinion","label":"S’adresser directement au pays","description":"Dire que les élus l’ont pris en otage. Ils le diront aussi de vous.","effects":{"popularite":3,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Négociations plus tendues"}],"news":"Allocution contre le blocage : la colère change de camp"}]},{"id":"etats-unis-primaires-interminables","title":"Des primaires qui n’en finissent pas","category":"politique","description":"Votre propre camp tient vingt-deux débats pour désigner un successeur déjà connu de tous. Les candidats se disputent un adjectif et les droits de leur propre slogan.","weight":5,"minTurn":4,"choices":[{"id":"rester-neutre","label":"Rester strictement neutre","description":"Prétendre que tout cela ne vous concerne pas.","effects":{"assemblee":-2,"popularite":1,"cohesion":1},"delayed":[{"delay":3,"effects":{"assemblee":1},"label":"Le camp se range derrière un nom"}],"news":"Primaires : le président « n’a pas d’avis », ce qui est un avis"},{"id":"soutenir","label":"Soutenir un champion","description":"Offrir votre soutien et votre calendrier.","effects":{"assemblee":3,"popularite":-2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Dynamique de campagne"}],"news":"Le président adoube un candidat, les autres boudent"},{"id":"raccourcir","label":"Proposer de raccourcir le calendrier","description":"Une réforme que personne n’a intérêt à voter.","effects":{"cohesion":2,"popularite":1,"assemblee":-2,"budget":1},"news":"Réforme des primaires : « bonne idée, pas pour cette année »"}]},{"id":"etats-unis-tempete-neige-blizzard","title":"Blizzard sur le Midwest","category":"climat","description":"Une tempête de neige paralyse les routes, les aéroports et les débats télévisés. Un gouverneur déclare l’état d’urgence, un autre déclare qu’il a déjà vu pire en 1978.","weight":5,"minTurn":3,"choices":[{"id":"garde-nationale","label":"Déployer la Garde nationale","description":"Dégager les axes et secourir les automobilistes.","effects":{"securite":3,"cohesion":2,"budget":-4,"popularite":1},"news":"Blizzard : la Garde nationale sort les pelleteuses"},{"id":"aide-rurale","label":"Soutenir les réseaux électriques ruraux","description":"Rétablir le courant avant tout le reste.","effects":{"cohesion":3,"ecologie":1,"budget":-5,"assemblee":2},"delayed":[{"delay":3,"effects":{"economie":1},"label":"Activité repartie"}],"news":"Courant rétabli dans les comtés enneigés, les élus aussi sont contents"},{"id":"conseils","label":"Conseiller de rester chez soi","description":"Un tweet présidentiel, une pelle imaginaire.","effects":{"popularite":-4,"cohesion":-2,"economie":-2,"budget":1},"news":"Blizzard : le conseil officiel est de ne pas sortir"}]},{"id":"etats-unis-gouverneurs-frontiere","title":"Bras de fer avec un gouverneur frontalier","category":"securite","description":"Un gouverneur installe ses propres barrières, ses propres règles et sa propre conférence de presse. La Constitution a une opinion, la Cour suprême en aura deux.","weight":5,"minTurn":3,"conditions":[{"gauge":"securite","op":"<","value":60}],"choices":[{"id":"proces-etat","label":"Saisir la justice fédérale","description":"Rappeler que la frontière relève de Washington.","effects":{"assemblee":-2,"cohesion":-1,"international":2,"securite":1},"delayed":[{"delay":4,"effects":{"popularite":-2},"label":"Procédure interminable"}],"news":"Washington assigne un gouverneur en justice, le gouverneur imprime des tee-shirts"},{"id":"accord","label":"Négocier un accord sur les moyens","description":"Plus d’agents fédéraux contre moins de discours.","effects":{"securite":3,"budget":-5,"cohesion":1},"news":"Accord frontalier : des agents en renfort, des micros en repos"},{"id":"laisser-faire","label":"Laisser faire pour ne pas aggraver","description":"Parier sur la fatigue médiatique.","effects":{"popularite":-3,"securite":-2,"cohesion":-3},"news":"Frontière : l’exécutif « suit la situation de près »"}]},{"id":"etats-unis-canicule-reseau-electrique","title":"Canicule et délestages","category":"climat","description":"Un dôme de chaleur plombe le Sud-Ouest. Les climatiseurs saturent le réseau, les opérateurs coupent le courant par quartiers tournants, les hôtels distribuent des éventails.","weight":5,"minTurn":4,"choices":[{"id":"urgence-energie","label":"Imposer des importations d’urgence","description":"Acheter de l’électricité à prix d’or.","effects":{"cohesion":3,"budget":-5,"economie":1},"delayed":[{"delay":3,"effects":{"pouvoirAchat":-2},"label":"Tarifs en hausse"}],"news":"Canicule : l’électricité arrive, la facture aussi"},{"id":"renouvelable","label":"Accélérer les projets solaires","description":"Poser des panneaux, y compris sur les toits des juges.","effects":{"ecologie":4,"economie":1,"budget":-4,"popularite":1},"delayed":[{"delay":4,"effects":{"economie":2,"ecologie":1},"label":"Premières mises en service"}],"news":"Plan solaire d’urgence : les toits du Nevada s’illuminent"},{"id":"appel-sobriete","label":"Appeler à la sobriété","description":"Baisser le thermostat, monter les excuses.","effects":{"popularite":-3,"ecologie":2,"cohesion":-1},"news":"Sobriété : le président suggère d’augmenter la température"}]},{"id":"etats-unis-primaire-fraude-allegations","title":"Accusations de fraude électorale","category":"politique","description":"Un candidat battu à la primaire dénonce des machines à voter « suspectes ». Les experts répondent calmement, les réseaux répondent bruyamment, les caméras répondent aux deux.","weight":4,"minTurn":5,"choices":[{"id":"audit","label":"Ordonner un audit indépendant","description":"Compter encore, pour que personne ne dise le contraire.","effects":{"cohesion":3,"budget":-2,"assemblee":1,"popularite":1},"news":"Audit indépendant : les chiffres sont les mêmes, les débats aussi"},{"id":"condamnation","label":"Condamner publiquement les accusations","description":"Défendre les institutions, au risque de cliver.","effects":{"cohesion":1,"popularite":-1,"international":2,"assemblee":-2},"news":"Le président défend le scrutin, une moitié du pays hausse les épaules"},{"id":"silence","label":"Ne rien dire","description":"Espérer que le cycle médiatique s’en lasse.","effects":{"popularite":-2,"cohesion":-3},"news":"Fraude alléguée : le silence présidentiel, interprété comme un communiqué"}]}]'),r=[{id:"etats-unis-budget-sans-shutdown",title:"Voter un budget sans fermeture",brief:"Un trimestre où personne ne ferme les parcs nationaux. Cela suppose un accord au Congrès, donc un miracle bien négocié.",objective:{type:"gaugeAtLeast",gauge:"assemblee",value:50},reward:{assemblee:2,economie:1},news:"Budget voté sans fermeture : le Capitole organise une fête modeste"},{id:"etats-unis-fin-de-primaires",title:"Sortir des primaires indemne",brief:"Gagner quatre points de popularité sans se disputer avec ceux qui l’espèrent aussi. Mission réputée impossible.",objective:{type:"gaugeGain",gauge:"popularite",value:4},reward:{popularite:2,cohesion:1},news:"Primaires : le président « surplombe », ce qui est sa manière de se reposer"},{id:"etats-unis-filibuster-evite",title:"Passer une loi malgré le filibuster",brief:"Faire adopter un texte avant la fin du trimestre. Le filibuster est un art, le contourner en est un autre.",objective:{type:"lawAdopted"},reward:{assemblee:2,popularite:1},news:"Le Sénat vote enfin, après quatorze heures de lecture d’un annuaire"},{id:"etats-unis-ponts-reparer",title:"Réparer les ponts avant qu’ils ne tombent",brief:"Un indice d’économie à 60 : les ponts tiennent, les chantiers aussi, les automobilistes un peu moins.",objective:{type:"gaugeAtLeast",gauge:"economie",value:60},reward:{economie:2,cohesion:1},news:"Infrastructures : un pont rouvre, un autre est déjà fermé pour symétrie"},{id:"etats-unis-adresse-heure-de-grande-ecoute",title:"S’adresser au pays en heure de grande écoute",brief:"Une allocution solennelle ce trimestre. Les chaînes interrompent leurs programmes, les commentateurs préparent leurs analyses avant même la première phrase.",objective:{type:"addressHeld"},reward:{popularite:2,cohesion:1},news:"Allocution en direct : douze minutes, quatre drapeaux, une audience honorable",room:"allocution",scene3d:"allocution"}],o=JSON.parse('{"medias":["Le Héraut de l’Union","Radio Route Libre","Chaîne Info Côte-à-Côte 24","La Gazette du Dernier Comté","Le Tribun du Midwest"],"journalistes":[{"id":"etats-unis-j-brenda-kowalczyk","name":"Brenda Kowalczyk-Lund","media":"Le Héraut de l’Union","style":"cinglante : pose une question de trois minutes pour obtenir un oui ou non","genre":"f"},{"id":"etats-unis-j-tyrone-beaumont","name":"Tyrone Beaumont-Pike","media":"Chaîne Info Côte-à-Côte 24","style":"sportif : commente chaque réponse comme une action de match","genre":"m"},{"id":"etats-unis-j-savannah-oduya","name":"Savannah Oduya-Reyes","media":"Radio Route Libre","style":"matinale : sourit en posant la question qui pique","genre":"f"},{"id":"etats-unis-j-walter-hargrove","name":"Walter Hargrove","media":"La Gazette du Dernier Comté","style":"nostalgique : tout allait mieux au temps des cabines téléphoniques","genre":"m"},{"id":"etats-unis-j-priya-castellano","name":"Priya Castellano","media":"Le Tribun du Midwest","style":"méthodique : arrive avec un dossier, trois graphiques et un surligneur","genre":"f"},{"id":"etats-unis-j-dwight-mulrooney","name":"Dwight Mulrooney","media":"Chaîne Info Côte-à-Côte 24","style":"indigné : commence toutes ses questions par « Franchement ? »","genre":"m"},{"id":"etats-unis-j-lucia-fairbanks","name":"Lucía Fairbanks","media":"Le Héraut de l’Union","style":"curieuse : pose la question que personne n’osait, puis une seconde"},{"id":"etats-unis-j-hank-tolliver","name":"Hank Tolliver-Nakamura","media":"Radio Route Libre","style":"bavard : prend l’antenne et oublie d’en rendre la moitié","genre":"m"}],"questions":[{"id":"etats-unis-q-popularite-sondage-bas","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":42},"text":"Monsieur le Président, votre cote d’approbation descend plus vite qu’un ascenseur de gratte-ciel. Vos conseillers vous montrent-ils encore les sondages, ou seulement les graphiques en couleur ?","answers":[{"tone":"franche","label":"Ils me montrent tout, même les chiffres qui piquent. Je préfère un mauvais sondage honnête à un beau graphique mensonger.","effects":{"popularite":4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les élus sentent le vent tourner"}],"news":"Le président avoue : « Je lis les sondages, et ils piquent »"},{"tone":"langue-de-bois","label":"Un sondage est une photographie, et je suis un long-métrage. Le scénario est excellent, la fin est en cours d’écriture.","effects":{"popularite":2,"economie":-2},"news":"Le président compare les sondages à une photographie"},{"tone":"offensive","label":"Ces sondages sont commandés par ceux qui rêvent d’un autre locataire à la Maison Blanche. Mon vrai sondage, c’est le jour du vote.","effects":{"popularite":5,"international":-2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les polémiques s’enveniment"}],"news":"Le président récuse les sondages : « Mon vrai sondage, c’est le vote »"}]},{"id":"etats-unis-q-popularite-trop-aime","theme":"popularite","condition":{"gauge":"popularite","op":">","value":62},"text":"Avec plus de 60 % d’opinions favorables, vous faites un score que même le hot-dog du stade n’obtient pas. N’avez-vous pas peur de n’avoir plus un seul adversaire à blâmer ?","answers":[{"tone":"franche","label":"Un peu, oui. La popularité est un prêt à taux variable : je prépare déjà la facture de la prochaine tempête.","effects":{"popularite":3,"budget":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"La prudence rassure les marchés"}],"news":"Le président se méfie de sa cote : « Un prêt à taux variable »"},{"tone":"langue-de-bois","label":"Je remercie les Américains pour leur confiance et je continue à travailler, comme toujours, comme partout, et à toute heure.","effects":{"popularite":2,"cohesion":-2},"news":"Le président remercie les Américains et poursuit son travail"},{"tone":"offensive","label":"Mes adversaires trouveront bien un nouveau sujet : ils ont toujours une réserve de colère en cannette, au frais.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"L’opposition bloque un vote en représailles"}],"news":"Le président raille ses adversaires et leur « colère en cannette »"}]},{"id":"etats-unis-q-economie-bourse-chute","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Les indices boursiers dégringolent et les retraités regardent leur épargne comme on regarde un barbecue qui brûle. Que dites-vous à ceux qui ont tout placé en actions ?","answers":[{"tone":"franche","label":"Que je comprends leur angoisse et que je ne promets pas de miracle. Les marchés remontent, mais pas par décret.","effects":{"popularite":3,"economie":-2},"delayed":[{"delay":2,"effects":{"economie":3},"label":"La confiance revient doucement"}],"news":"Le président aux épargnants : « Pas de miracle, mais pas de panique »"},{"tone":"langue-de-bois","label":"Les fondamentaux de l’économie américaine sont solides, et ce que l’on voit n’est qu’une respiration. Gardons nos nerfs.","effects":{"economie":2,"popularite":-3},"news":"« Une simple respiration » : le président minimise la chute"},{"tone":"offensive","label":"Ceux qui parient contre l’Amérique perdent toujours. Qu’ils vendent, nous rachèterons moins cher et en rirons plus fort.","effects":{"economie":4,"international":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"budget":-3},"label":"Le plan de rachat coûte plus cher que prévu"}],"news":"Le président défie les vendeurs : « Nous rachèterons moins cher »"}]},{"id":"etats-unis-q-economie-record-bourse","theme":"economie","condition":{"gauge":"economie","op":">","value":68},"text":"La croissance est vigoureuse et les indices battent des records. Mais les voisins d’en face se demandent s’ils verront un jour la couleur de ce boom. Qui en profite vraiment ?","answers":[{"tone":"franche","label":"Pas assez de monde, et je le dis. Le boom doit atteindre la salle à manger et pas seulement la salle des marchés.","effects":{"pouvoirAchat":4,"economie":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les salariés remarquent la différence"}],"news":"Le président : « La croissance doit entrer dans les foyers »"},{"tone":"langue-de-bois","label":"Les ménages bénéficient d’un environnement favorable à l’emploi, à l’investissement et à la création de valeur partagée.","effects":{"economie":2,"cohesion":-2},"news":"Le président vante « une valeur partagée » sans la partager"},{"tone":"offensive","label":"Ceux qui n’aiment pas la prospérité peuvent toujours la refuser. Je n’ai encore vu personne rendre sa fiche de paie.","effects":{"economie":3,"popularite":2,"cohesion":-4},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Une chronique virale tourne la formule en dérision"}],"news":"Le président : « Personne n’a rendu sa fiche de paie »"}]},{"id":"etats-unis-q-budget-dette-vertigineuse","theme":"budget","condition":{"gauge":"budget","op":"<","value":35},"text":"La dette fédérale a désormais plus de zéros qu’un compte à rebours de lancement de fusée. À quel moment, au juste, quelqu’un doit-il rendre la monnaie ?","answers":[{"tone":"franche","label":"À un moment où nos enfants le feront à notre place si nous n’agissons pas. Je propose des économies, un calendrier et du courage.","effects":{"budget":5,"popularite":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les élus se déchirent sur les coupes"}],"news":"Dette fédérale : le président promet des économies et un calendrier"},{"tone":"langue-de-bois","label":"La dette est soutenable tant que la croissance, la confiance et la discipline avancent de concert, bras dessus bras dessous.","effects":{"economie":2,"budget":-2},"news":"Dette : le président plaide pour une marche « bras dessus bras dessous »"},{"tone":"offensive","label":"Les pays qui nous font la leçon ont des dettes en pesos, en yens ou en promesses. La nôtre au moins est en dollars.","effects":{"budget":-2,"economie":4,"international":-3},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Plusieurs capitales réclament des excuses"}],"news":"Le président renvoie les donneurs de leçons à leurs propres dettes"}]},{"id":"etats-unis-q-budget-excedent-fantome","theme":"budget","condition":{"gauge":"budget","op":">","value":60},"text":"Pour une fois, les comptes sont à peu près équilibrés. Tout le monde veut sa part de gâteau : défense, santé, routes, cinéma de plein air. Quelle part gardez-vous pour une année de pluie ?","answers":[{"tone":"franche","label":"Une bonne moitié, et je vais l’expliquer sans fard. Un budget équilibré n’est pas une fête, c’est un parapluie.","effects":{"budget":4,"popularite":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"La réserve rassure les agences"}],"news":"Le président met la moitié de l’excédent de côté : « un parapluie »"},{"tone":"langue-de-bois","label":"Chaque secteur sera traité avec équité, dans un esprit de dialogue, de responsabilité et de répartition harmonieuse.","effects":{"budget":-2,"assemblee":3},"news":"Excédent : le président promet une « répartition harmonieuse »"},{"tone":"offensive","label":"Je baisse les impôts de tout le monde, tout de suite. Si la pluie vient, on fera comme les années précédentes : on se mouillera.","effects":{"popularite":5,"pouvoirAchat":3,"budget":-5},"delayed":[{"delay":3,"effects":{"budget":-3},"label":"La facture arrive avec le premier orage"}],"news":"Le président baisse les impôts : « Si la pluie vient, on se mouillera »"}]},{"id":"etats-unis-q-pouvoirachat-prix-oeufs","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":40},"text":"Le prix des œufs, de l’essence et du loyer grimpe plus vite que les marches d’un stade. Que répondez-vous à une famille qui compare désormais le prix de chaque rayon avant de remplir son caddie ?","answers":[{"tone":"franche","label":"Que je vois ces étiquettes aussi, et que je ne ferai pas semblant. Un plafond sur certains loyers et un coup de pouce aux ménages.","effects":{"pouvoirAchat":5,"budget":-3},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les ménages respirent un peu"}],"news":"Le président annonce un coup de pouce aux ménages et un plafond de loyers"},{"tone":"langue-de-bois","label":"Nous suivons de près l’évolution des prix et resterons très attentifs à toute évolution significative de la situation.","effects":{"pouvoirAchat":2,"popularite":-3},"news":"Prix : le président « reste très attentif », les ménages un peu moins"},{"tone":"offensive","label":"Les distributeurs s’engraissent, qu’on les convoque et qu’on les fasse passer en caisse. L’ère du chariot vide est terminée.","effects":{"pouvoirAchat":4,"popularite":2,"economie":-4},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Les distributeurs réduisent leurs embauches"}],"news":"Le président convoque la grande distribution : « Passez en caisse »"}]},{"id":"etats-unis-q-securite-criminalite-villes","theme":"securite","condition":{"gauge":"securite","op":"<","value":45},"text":"Dans plusieurs grandes villes, les habitants disent ne plus se sentir en sécurité à la tombée de la nuit. Les maires réclament des moyens, les gouverneurs des principes. Qui paie ?","answers":[{"tone":"franche","label":"L’État fédéral, avec les villes, et pas à la place d’elles. Plus de policiers de proximité, mais aussi des conseillers et des lampadaires.","effects":{"securite":5,"budget":-4},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"La présence de proximité apaise certains quartiers"}],"news":"Sécurité : le président finance policiers de proximité et lampadaires"},{"tone":"langue-de-bois","label":"La sécurité est une responsabilité partagée entre tous les niveaux de l’administration, dans le respect de la Constitution.","effects":{"securite":2,"popularite":-3},"news":"Sécurité : le président invoque la « responsabilité partagée »"},{"tone":"offensive","label":"Si les maires ne tiennent pas leurs rues, la Garde nationale viendra les aider, avec ou sans invitation, avec ou sans café.","effects":{"securite":5,"popularite":2,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":-3},"label":"Le déploiement nourrit un bras de fer politique"}],"news":"Le président menace d’envoyer la Garde nationale dans les villes"}]},{"id":"etats-unis-q-cohesion-pays-fracture","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":35},"text":"Les sondages montrent que beaucoup d’Américains ne s’adressent plus la parole d’un bord à l’autre, même à Thanksgiving. Avez-vous une recette pour que la dinde passe sans dispute ?","answers":[{"tone":"franche","label":"Parler de ce qui nous unit : les voisins, les stades, les ponts. Je commence par écouter ceux qui ne m’ont pas élu.","effects":{"cohesion":5,"popularite":-2},"delayed":[{"delay":3,"effects":{"assemblee":2},"label":"Des élus de l’autre bord acceptent de dialoguer"}],"news":"Le président veut écouter « ceux qui ne l’ont pas élu »"},{"tone":"langue-de-bois","label":"Les Américains partagent bien plus de valeurs qu’on ne le dit. L’unité est une œuvre de longue haleine, et nous y travaillons.","effects":{"cohesion":2,"popularite":-2},"news":"Le président : « L’unité est une œuvre de longue haleine »"},{"tone":"offensive","label":"La division vient surtout des chaînes d’info qui vivent de la dispute. Je propose une trêve : une semaine sans insultes à l’antenne.","effects":{"cohesion":3,"popularite":3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Les chaînes répliquent par un débat de six heures"}],"news":"Le président propose « une semaine sans insultes à l’antenne »"}]},{"id":"etats-unis-q-cohesion-unite-suspecte","theme":"cohesion","condition":{"gauge":"cohesion","op":">","value":62},"text":"Républicains et démocrates se sont parlé poliment trois semaines de suite. Les experts s’inquiètent : est-ce un virus, une anomalie statistique, ou le début de quelque chose ?","answers":[{"tone":"franche","label":"Le début de quelque chose, j’espère. Ne le gâchons pas : un désaccord argumenté vaut mieux qu’un accord de façade.","effects":{"cohesion":3,"assemblee":2,"popularite":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Le climat plus serein plaît aux électeurs"}],"news":"Le président : « Un désaccord argumenté vaut mieux qu’un faux accord »"},{"tone":"langue-de-bois","label":"Le dialogue est la clé de toute démocratie saine, et nous avons la chance d’en bénéficier. Je ne commenterai pas davantage.","effects":{"cohesion":2,"popularite":-2},"news":"Trêve politique : le président refuse de commenter l’anomalie"},{"tone":"offensive","label":"Profitez-en, ça ne durera pas. Dès le prochain budget, chacun retrouvera sa couleur, ses tweets et ses vieilles rancunes.","effects":{"popularite":3,"cohesion":-3,"assemblee":-2},"news":"Le président sur la trêve : « Profitez-en, ça ne durera pas »"}]},{"id":"etats-unis-q-ecologie-forages-federaux","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":35},"text":"Entre les permis de forage sur les terres fédérales et les pick-up toujours plus larges, l’empreinte carbone américaine reste colossale. Quand la route cessera-t-elle d’être plus large que le climat ?","answers":[{"tone":"franche","label":"Je sais que nous devons faire plus. Un fonds de transition pour les États producteurs et des bornes de recharge partout.","effects":{"ecologie":5,"budget":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les nouvelles filières créent des emplois"}],"news":"Le président annonce un fonds de transition et des bornes partout"},{"tone":"langue-de-bois","label":"Nous poursuivons une approche équilibrée entre sécurité énergétique, compétitivité et ambitions climatiques à long terme.","effects":{"ecologie":2,"popularite":-2},"news":"Climat : le président cherche « une approche équilibrée »"},{"tone":"offensive","label":"Mon pick-up pollue moins que les sermons de ceux qui prennent le jet privé pour aller au sommet du climat.","effects":{"popularite":3,"economie":3,"ecologie":-4,"international":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Plusieurs alliés dénoncent l’attitude américaine"}],"news":"Le président défend son pick-up face aux « sermons du jet privé »"}]},{"id":"etats-unis-q-ecologie-renouvelables-record","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":58},"text":"Les éoliennes poussent dans les champs, les panneaux sur les toits. Les propriétaires de ranchs réclament un droit de vote sur la direction du vent. Que leur répondez-vous ?","answers":[{"tone":"franche","label":"Que ceux qui accueillent des turbines doivent être payés, et bien. Une transition juste commence par un chèque, pas par un sermon.","effects":{"ecologie":3,"cohesion":3,"budget":-4},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les fermiers touchent leurs premiers loyers"}],"news":"Le président : « Une transition juste commence par un chèque »"},{"tone":"langue-de-bois","label":"Le vent appartient à tous, mais les bénéfices seront répartis selon des modalités à définir dans une prochaine concertation.","effects":{"ecologie":2,"cohesion":-2},"news":"Éolien : le président renvoie le partage du vent à « une concertation »"},{"tone":"offensive","label":"Le vent ne vote pas, mais il souffle pour l’économie américaine. Ceux qui bloquent les projets bloquent aussi des emplois.","effects":{"economie":4,"ecologie":2,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les élus ruraux s’opposent aux projets"}],"news":"Le président : « Le vent ne vote pas, mais il souffle pour l’économie »"}]},{"id":"etats-unis-q-international-allies-doutent","theme":"international","condition":{"gauge":"international","op":"<","value":42},"text":"Plusieurs alliés disent ne plus savoir si l’Amérique est un partenaire, un arbitre ou un spectateur. Une capitale vous a même demandé si vous receviez toujours vos appels. Rappelez-vous leur numéro ?","answers":[{"tone":"franche","label":"Je le connais par cœur. Je vais leur rendre visite, écouter leurs inquiétudes et répondre à leurs demandes concrètes.","effects":{"international":5,"popularite":-2},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"Les engagements promis coûtent cher"}],"news":"Le président part en tournée pour rassurer les alliés"},{"tone":"langue-de-bois","label":"L’Amérique demeure un partenaire engagé, fiable et attaché à ses alliances, dans un monde en mouvement constant.","effects":{"international":2,"popularite":-2},"news":"« Un partenaire fiable » : le président rassure sans rassurer"},{"tone":"offensive","label":"Qu’ils paient leur part des dépenses de défense, et le téléphone sonnera moins souvent dans leur sens que dans le mien.","effects":{"budget":3,"popularite":3,"international":-5},"delayed":[{"delay":3,"effects":{"international":-2},"label":"Des sommets sont reportés dans l’irritation"}],"news":"Le président aux alliés : « Payez votre part de la défense »"}]},{"id":"etats-unis-q-international-gendarme-fatigue","theme":"international","condition":{"gauge":"international","op":">","value":70},"text":"L’influence américaine est à son apogée, et pourtant les électeurs vous demandent pourquoi il faudrait encore tout régler au bout du monde. Jusqu’où irez-vous pour être le gendarme du monde ?","answers":[{"tone":"franche","label":"Aussi loin que nos intérêts et nos principes l’exigent, mais pas plus loin qu’un dollar bien dépensé à la maison.","effects":{"international":3,"budget":-3,"popularite":2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Les électeurs réclament des comptes"}],"news":"Le président : « Aussi loin qu’un dollar bien dépensé »"},{"tone":"langue-de-bois","label":"Nous agirons avec nos partenaires, dans le cadre du droit international et avec la mesure qu’exige chaque situation.","effects":{"international":2,"popularite":-2},"news":"Gendarme du monde : le président invoque la « mesure »"},{"tone":"offensive","label":"Il y a toujours quelqu’un pour dire qu’on en fait trop, jusqu’au jour où il appelle pour qu’on en fasse davantage.","effects":{"international":4,"popularite":2,"cohesion":-3,"budget":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Le débat sur l’isolationnisme repart"}],"news":"Le président : « On nous accuse d’en faire trop, puis on nous rappelle »"}]},{"id":"etats-unis-q-assemblee-blocage-soixante-voix","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":35},"text":"Au Sénat, il faut soixante voix pour avancer, et vous en avez à peu près quarante-deux. À ce rythme, vos projets de loi finiront-ils dans le même musée que le premier aérostat ?","answers":[{"tone":"franche","label":"Je négocie loi par loi, voix par voix, café par café. C’est lent, mais c’est la seule méthode qui marche vraiment.","effects":{"assemblee":5,"popularite":-2},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"Les compromis coûtent cher en concessions"}],"news":"Le président négocie « voix par voix, café par café »"},{"tone":"langue-de-bois","label":"Le Congrès exerce son rôle constitutionnel, et l’exécutif respecte pleinement la séparation des pouvoirs qui nous est chère.","effects":{"assemblee":2,"popularite":-3},"news":"Le président salue la « séparation des pouvoirs » face au blocage"},{"tone":"offensive","label":"S’ils veulent la paralysie, je gouvernerai par décret et ils découvriront que le crayon pèse plus lourd que la procédure.","effects":{"popularite":3,"economie":2,"assemblee":-5,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Le Congrès prépare une riposte juridique"}],"news":"Le président brandit le décret : « Le crayon pèse plus lourd »"}]},{"id":"etats-unis-q-assemblee-congres-docile","theme":"assemblee","condition":{"gauge":"assemblee","op":">","value":62},"text":"Le Congrès vote vos textes presque sans broncher. Certains commentateurs disent que les contre-pouvoirs sont partis en vacances. Qui, dans votre entourage, ose encore vous dire non ?","answers":[{"tone":"franche","label":"Mon équipe, mes juges et ma femme de ménage, hélas pour moi. Je les encourage à le faire plus tôt qu’après le vote.","effects":{"cohesion":3,"popularite":2,"assemblee":-3},"news":"Le président : « Plusieurs personnes me disent non, et c’est bien »"},{"tone":"langue-de-bois","label":"Le Congrès est souverain et le vote est libre. Ce qui est voté répond aux attentes du pays, sans qu’il soit besoin d’en dire plus.","effects":{"assemblee":2,"cohesion":-2},"news":"Majorité docile : le président assure que « le vote est libre »"},{"tone":"offensive","label":"Je ne vois pas ce qu’il y a à reprocher à une majorité qui fait son travail. Il suffit de l’avoir, comme un bon barbecue.","effects":{"assemblee":4,"popularite":2,"cohesion":-3,"international":-2},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Les éditorialistes dénoncent la dérive"}],"news":"Le président défend sa majorité : « On l’a, comme un bon barbecue »"}]},{"id":"etats-unis-q-culture-super-bowl","theme":"popularite","text":"Dimanche, la moitié du pays regarde la finale du championnat de football américain, l’autre moitié regarde les publicités. Quel camp êtes-vous, et pour qui allez-vous faire semblant de crier ?","answers":[{"tone":"franche","label":"Je regarde le match, je critique l’arbitrage et je mange trop d’ailes de poulet. Comme tout le monde, sauf l’arbitre.","effects":{"popularite":4,"cohesion":2,"economie":-2},"delayed":[{"delay":2,"effects":{"popularite":-1},"label":"Une photo de la sauce sur la cravate fait le tour du pays"}],"news":"Le président assume ses ailes de poulet devant la finale"},{"tone":"langue-de-bois","label":"Je soutiendrai chaleureusement les deux équipes, leurs supporters, leurs mascottes et l’ensemble de la filière sportive nationale.","effects":{"popularite":2,"cohesion":-2},"news":"Finale : le président soutient « les deux équipes et les mascottes »"},{"tone":"offensive","label":"Je soutiens l’équipe qui paiera ses impôts dans mon État. Pour les publicités, je réclame un temps de parole égal.","effects":{"popularite":3,"budget":3,"cohesion":-3},"news":"Le président réclame « un temps de parole égal » pour les publicités"}]},{"id":"etats-unis-q-culture-thanksgiving","theme":"cohesion","text":"Chaque année, des familles américaines évitent les sujets politiques à table en parlant de la dinde. Quelle règle diplomatique appliquez-vous quand votre oncle ouvre la discussion sur les impôts ?","answers":[{"tone":"franche","label":"Je lui ressers une part de tarte à la citrouille. Et, si ça ne suffit pas, une seconde, avec de la crème.","effects":{"cohesion":4,"popularite":3,"economie":-2},"news":"Le président sur Thanksgiving : « La tarte règle plus que les débats »"},{"tone":"langue-de-bois","label":"Thanksgiving est un moment d’unité nationale, de gratitude et de convivialité. Chacun doit s’y retrouver, sans exception.","effects":{"cohesion":2,"popularite":-2},"news":"Thanksgiving : le président célèbre « gratitude et convivialité »"},{"tone":"offensive","label":"Mon oncle a toujours tort, mais on le garde pour la bonne cause : il apporte les boissons. C’est ça, la démocratie.","effects":{"popularite":4,"cohesion":-3},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"L’oncle du président se fâche en direct"}],"news":"Le président sur son oncle : « Il a tort, mais il apporte les boissons »"}]},{"id":"etats-unis-q-culture-systeme-metrique","theme":"international","text":"Les Américains mesurent en pouces, en livres et en gallons, alors que presque tout le reste du monde utilise le mètre. Allez-vous un jour nous faire entrer dans le système métrique ?","answers":[{"tone":"franche","label":"Soyons sérieux : on passera au métrique le jour où un gallon d’essence coûtera moins cher qu’un litre. Je travaille à la transition.","effects":{"international":4,"popularite":-2,"economie":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les industriels exportent plus facilement"}],"news":"Le président envisage un passage progressif au système métrique"},{"tone":"langue-de-bois","label":"Nos unités de mesure font partie de notre patrimoine, mais le dialogue avec nos partenaires reste ouvert sur ce sujet délicat.","effects":{"popularite":2,"international":-2},"news":"Système métrique : le président garde « le dialogue ouvert »"},{"tone":"offensive","label":"Un pied, c’est un pied. Si les autres pays veulent mesurer en mètres, qu’ils achètent d’abord nos règles.","effects":{"popularite":4,"economie":2,"international":-4},"news":"Le président : « Un pied, c’est un pied. »"}]},{"id":"etats-unis-q-culture-pourboire","theme":"pouvoirAchat","text":"Entre les pourboires à 20 %, la suggestion à 25 % et le bouton « autre » qui vous regarde droit dans les yeux, les Américains disent qu’ils dépensent plus en bonne conscience qu’en dîner. Comptez-vous y mettre de l’ordre ?","answers":[{"tone":"franche","label":"Les serveurs doivent être mieux payés par leurs employeurs, pour qu’on ne dépende pas de nos remords au moment de payer.","effects":{"pouvoirAchat":3,"popularite":2,"economie":-3},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Les restaurateurs relèvent leurs prix"}],"news":"Pourboires : le président veut de meilleurs salaires pour les serveurs"},{"tone":"langue-de-bois","label":"Le pourboire relève de la liberté individuelle et de la générosité de chacun, sans que l’État n’ait à s’en mêler.","effects":{"economie":2,"pouvoirAchat":-2},"news":"Pourboires : le président y voit « la générosité de chacun »"},{"tone":"offensive","label":"Je propose un pourboire pour le Congrès : le jour où il vote à temps un budget, on lui laisse 20 % de dignité.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"news":"Le président propose un pourboire au Congrès pour un budget à temps"}]},{"id":"etats-unis-q-culture-heure-ete","theme":"popularite","text":"Deux fois par an, tout un pays change d’heure et passe trois jours à se demander quelle heure il est. Allez-vous un jour décider qui, du matin ou du soir, a la priorité sur le soleil ?","answers":[{"tone":"franche","label":"Je suis pour une heure fixe, l’été. Le soir restera long, le matin restera court, et personne n’aura à régler le four.","effects":{"popularite":4,"economie":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les États du nord se plaignent des matins sombres"}],"news":"Heure d’été : le président veut la garder toute l’année"},{"tone":"langue-de-bois","label":"Ce dossier mérite une étude approfondie qui prendra en compte les spécificités de chaque fuseau et de chaque habitude.","effects":{"popularite":-2,"cohesion":2},"news":"Heure d’été : le président annonce « une étude approfondie »"},{"tone":"offensive","label":"Je laisse chaque État choisir son heure. On aura des horloges qui se disputent aux frontières, et ce sera très américain.","effects":{"popularite":3,"cohesion":-4,"economie":2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les horaires de transport deviennent illisibles"}],"news":"Le président laisse chaque État choisir son heure : chaos assuré"}]},{"id":"etats-unis-q-culture-route-66","theme":"ecologie","text":"L’Américain moyen fait plus de kilomètres en voiture que ses voisins ne font de pas, et un road trip reste un droit non écrit. Comment concilier la liberté de la route et celle de respirer ?","answers":[{"tone":"franche","label":"En rendant la route plus propre et le train plus tentant. Personne n’a dit qu’il fallait renoncer à traverser le pays.","effects":{"ecologie":4,"budget":-3},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Le premier train grande vitesse suscite l’enthousiasme"}],"news":"Le président veut des routes plus propres et des trains plus tentants"},{"tone":"langue-de-bois","label":"La liberté de circuler est fondamentale, tout comme la préservation de notre environnement. Il s’agit de trouver un chemin équilibré.","effects":{"ecologie":2,"popularite":-2},"news":"Road trip et climat : le président cherche « un chemin équilibré »"},{"tone":"offensive","label":"Un Américain sans voiture, c’est un cow-boy sans cheval. Les écolos n’ont qu’à faire du stop pour convaincre les autres.","effects":{"popularite":4,"economie":3,"ecologie":-4,"cohesion":-2},"news":"Le président : « Un Américain sans voiture, un cow-boy sans cheval »"}]},{"id":"etats-unis-q-crise-ouragan-cote-est","theme":"crise","crisisId":"etats-unis-ouragan-cote-est","text":"L’ouragan a laissé des quartiers sans électricité et des habitants sur les toits. L’agence fédérale est accusée d’être arrivée avec le ruban d’un chantier plutôt qu’avec des camions. Qui est responsable ?","answers":[{"tone":"franche","label":"Moi, en dernier ressort. Les erreurs seront examinées publiquement et chaque dollar d’aide sera suivi à la trace.","effects":{"popularite":4,"budget":-3},"delayed":[{"delay":2,"effects":{"cohesion":3},"label":"Les sinistrés reconnaissent l’effort de transparence"}],"news":"Ouragan : le président assume la responsabilité des retards"},{"tone":"langue-de-bois","label":"L’agence fédérale, les États et les collectivités ont fait ce qu’ils pouvaient, dans des conditions difficiles et un calendrier tendu.","effects":{"securite":2,"popularite":-3},"news":"Ouragan : le président salue « les efforts de tous » sans nommer les retards"},{"tone":"offensive","label":"Quand le vent se lève, certains gouverneurs se souviennent de l’État fédéral. Ils l’oublient quand il s’agit de payer.","effects":{"securite":3,"popularite":2,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Les gouverneurs bloquent un texte d’aide"}],"news":"Ouragan : le président renvoie les gouverneurs à leurs oublis"}]},{"id":"etats-unis-q-crise-shutdown-salaires","theme":"crise","crisisId":"etats-unis-shutdown-budgetaire","text":"Faute de budget, les services fédéraux ferment, les parcs nationaux aussi, et des contrôleurs aériens travaillent sans salaire. Combien de temps les Américains devront-ils compter sur la patience des autres ?","answers":[{"tone":"franche","label":"Pas un jour de plus que nécessaire. Je reçois les chefs de groupe ce soir, avec du café et la porte fermée à clé.","effects":{"assemblee":4,"popularite":-2,"budget":-2},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Un accord s’esquisse enfin"}],"news":"Fermeture des services : le président enferme les chefs de groupe"},{"tone":"langue-de-bois","label":"Nous restons mobilisés pour assurer la continuité des services essentiels, en attendant que chacun prenne ses responsabilités.","effects":{"securite":2,"popularite":-3},"news":"Fermeture des services : le président appelle chacun à « prendre ses responsabilités »"},{"tone":"offensive","label":"Que l’opposition rouvre le gouvernement ou qu’elle explique aux contrôleurs aériens pourquoi leur paie a été retenue en otage.","effects":{"popularite":4,"cohesion":-3,"assemblee":-4},"delayed":[{"delay":2,"effects":{"economie":-3},"label":"Les retards aériens plombent l’activité"}],"news":"Fermeture des services : le président accuse l’opposition de prise d’otages"}]},{"id":"etats-unis-q-crise-blizzard-midwest","theme":"crise","crisisId":"etats-unis-tempete-neige-blizzard","text":"Un blizzard a figé le Midwest : routes fermées, écoles closes, camions de sel introuvables. Un habitant déclare avoir attendu les chasse-neige plus longtemps que la fin de l’hiver. Que lui répondez-vous ?","answers":[{"tone":"franche","label":"Je suis désolé, et j’ai demandé l’inventaire des chasse-neige disponibles. Nous financerons du matériel avant le prochain hiver.","effects":{"securite":3,"popularite":3,"budget":-4},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Le réseau routier retrouve vite sa fluidité"}],"news":"Blizzard : le président promet des chasse-neige avant le prochain hiver"},{"tone":"langue-de-bois","label":"Les équipes sont à pied d’œuvre et la situation évolue favorablement, même si elle reste délicate dans certains comtés.","effects":{"securite":2,"popularite":-3},"news":"Blizzard : « La situation évolue favorablement », dit le président"},{"tone":"offensive","label":"Un Midwestien digne de ce nom a une pelle, une thermos et un peu de patience. Le froid, ça forge le caractère.","effects":{"popularite":3,"cohesion":2,"securite":-4},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Un maire demande où sont passés les chasse-neige"}],"news":"Blizzard : le président vante la pelle et le caractère"}]},{"id":"etats-unis-q-crise-canicule-delestages","theme":"crise","crisisId":"etats-unis-canicule-reseau-electrique","text":"Sous la canicule, le réseau électrique craque et des délestages privent des villes de climatisation en plein après-midi. Faut-il choisir entre le confort et le courant ?","answers":[{"tone":"franche","label":"Non, mais il faut investir dans un réseau qui ne dépende pas d’une seule centrale ni d’une seule prière. Le chantier commence cette année.","effects":{"ecologie":3,"securite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"economie":3},"label":"Les chantiers de modernisation créent des emplois"}],"news":"Canicule : le président lance la modernisation du réseau électrique"},{"tone":"langue-de-bois","label":"Les services concernés travaillent en lien étroit avec les opérateurs. Nous appelons chacun à la modération de sa consommation.","effects":{"ecologie":2,"popularite":-3},"news":"Canicule : le président appelle à « la modération » devant la clim"},{"tone":"offensive","label":"Les opérateurs privés ont encaissé les profits pendant dix ans et débranchent maintenant les ventilateurs. Ils auront des comptes à rendre.","effects":{"popularite":4,"securite":2,"economie":-3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"economie":-3},"label":"Les investisseurs se retirent du secteur"}],"news":"Délestages : le président somme les opérateurs de rendre des comptes"}]},{"id":"etats-unis-q-crise-gouverneur-frontiere","theme":"crise","crisisId":"etats-unis-gouverneurs-frontiere","text":"Un gouverneur frontalier a décidé d’appliquer sa propre politique migratoire, avec ses propres barrières et sa propre communication. Où s’arrête l’autorité fédérale, et où commence la sienne ?","answers":[{"tone":"franche","label":"Là où la Constitution le dit, c’est-à-dire pas toujours là où il le croit. Je ne cherche pas l’affrontement, mais la loi vaut pour tous.","effects":{"securite":3,"international":2,"cohesion":-3},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Des élus des deux bords demandent un cadre clair"}],"news":"Gouverneur frontalier : le président rappelle que « la loi vaut pour tous »"},{"tone":"langue-de-bois","label":"Les questions de compétences entre l’État fédéral et les États sont des matières complexes que les juristes examineront avec soin.","effects":{"securite":2,"popularite":-3},"news":"Frontière : le président renvoie le conflit aux « juristes »"},{"tone":"offensive","label":"Si le gouverneur veut jouer au chef d’État, je lui prêterai volontiers un bureau, un budget et des avocats. Ils en auront besoin.","effects":{"popularite":4,"securite":2,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":-3},"label":"Le gouverneur obtient un soutien de ses homologues"}],"news":"Le président au gouverneur : « Je vous prête un bureau et des avocats »"}]},{"id":"etats-unis-q-crise-communication-ratee","theme":"crise","text":"Une consigne de sécurité publiée par votre administration a été comprise de trois façons différentes, dont deux contradictoires. Les réseaux sociaux se demandent si vous avez un relecteur. Qui l’a rédigée ?","answers":[{"tone":"franche","label":"Un de mes services, et j’en prends la responsabilité. Un nouveau texte, clair, avec des phrases courtes et des verbes.","effects":{"popularite":3,"securite":2,"budget":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Le nouveau texte est jugé lisible, c’est une première"}],"news":"Consigne ratée : le président promet un texte « avec des verbes »"},{"tone":"langue-de-bois","label":"Les consignes ont été diffusées en urgence, et des améliorations seront apportées à l’avenir dans un souci de clarté.","effects":{"securite":2,"popularite":-3},"news":"Consigne contradictoire : le président promet « des améliorations »"},{"tone":"offensive","label":"Il y a trois lectures parce que trois chaînes ont voulu avoir raison. Je laisse la lecture de vos commentaires à ceux qui ont du temps.","effects":{"popularite":3,"cohesion":-3,"international":-2},"news":"Consigne brouillée : le président renvoie la faute aux chaînes d’info"}]},{"id":"etats-unis-q-crise-cellule-sang-froid","theme":"crise","text":"En pleine crise, on raconte que votre cellule de crise a passé vingt minutes à chercher le bon numéro de salle. Est-ce vrai, et la salle de crise a-t-elle une carte du bâtiment ?","answers":[{"tone":"franche","label":"C’est vrai, quinze minutes, pas vingt. Nous avons depuis ajouté des panneaux, des flèches et un plan. Rien de plus simple, rien de plus honnête.","effects":{"popularite":4,"securite":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"L’aveu fait sourire plus qu’il ne fâche"}],"news":"Salle de crise introuvable : le président confirme « quinze minutes »"},{"tone":"langue-de-bois","label":"Les procédures de gestion de crise sont revues en continu, à la lumière de chaque retour d’expérience, afin d’améliorer la réactivité.","effects":{"securite":2,"popularite":-2},"news":"Salle de crise : le président annonce un « retour d’expérience »"},{"tone":"offensive","label":"Pendant que vous comptiez mes minutes, nous avions déjà décidé et agi. C’est le résultat qui compte, pas le plan du couloir.","effects":{"securite":3,"popularite":2,"cohesion":-3},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Une vidéo du couloir confus devient virale"}],"news":"Salle de crise : « Le résultat compte, pas le plan du couloir »"}]},{"id":"etats-unis-q-scandale-golf-lobbyiste","theme":"scandale","text":"Un lobbyiste affirme avoir invité l’un de vos conseillers à un week-end de golf, puis lui avoir offert un trou-en-un. Votre conseiller parle d’une coïncidence. Les greens, eux, parlent de l’article 12.","answers":[{"tone":"franche","label":"Mon conseiller rendra les clubs, les chaussures et le trou-en-un. L’enquête sera menée par un contrôleur indépendant, et j’en publierai les conclusions.","effects":{"popularite":3,"cohesion":2,"assemblee":-3},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"La publication du rapport est saluée"}],"news":"Golf et lobbyiste : le président exige un contrôleur indépendant"},{"tone":"langue-de-bois","label":"Mon conseiller est un homme intègre. Il a pris acte de la polémique et se tient à la disposition de toute procédure légitime.","effects":{"assemblee":2,"popularite":-4},"news":"Golf et lobbyiste : le président défend un conseiller « intègre »"},{"tone":"offensive","label":"Le golf est un sport comme un autre, et certains ont plus de temps pour le critiquer que pour le jouer. Passons à l’essentiel.","effects":{"popularite":2,"economie":2,"cohesion":-3,"assemblee":-3},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Un nouveau lobbyiste confirme avoir tout organisé"}],"news":"Golf et lobbyiste : le président juge la polémique « hors sujet »"}]},{"id":"etats-unis-q-scandale-messagerie-perso","theme":"scandale","text":"On a découvert que plusieurs notes officielles avaient transité par la messagerie personnelle d’un membre de votre cabinet, nommée « jardinage-et-fusion ». Y a-t-il eu des fuites, ou seulement des tomates ?","answers":[{"tone":"franche","label":"Il y a eu un manquement et une règle bafouée. Le responsable change de poste et tout le personnel suit une formation numérique.","effects":{"securite":3,"popularite":2,"cohesion":-2},"delayed":[{"delay":2,"effects":{"securite":2},"label":"Les protocoles sont durcis dans tout l’exécutif"}],"news":"Messagerie personnelle : le président sanctionne et forme son personnel"},{"tone":"langue-de-bois","label":"Un incident d’ordre technique est à l’examen. Les mesures appropriées seront prises en temps utile, conformément aux procédures en vigueur.","effects":{"securite":2,"popularite":-3},"news":"Messagerie personnelle : le président annonce un « incident technique »"},{"tone":"offensive","label":"On parle de jardinage depuis une heure, il paraît que c’est de la haute sécurité. Cherchez plutôt qui a publié ces notes dans la presse.","effects":{"popularite":3,"international":-2,"securite":-3},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Les journalistes défendent leurs sources"}],"news":"Messagerie personnelle : le président attaque la presse et ses sources"}]},{"id":"etats-unis-q-scandale-food-truck","theme":"scandale","text":"Un marché fédéral de restauration pour vos équipes a été attribué à un food truck appartenant au beau-frère d’un conseiller. Le burrito était excellent, dit-on, mais l’appel d’offres ressemblait à une recette de famille.","answers":[{"tone":"franche","label":"Le burrito était bon, mais la règle est la règle. Le marché est annulé, rouvert et attribué sur dossier, sans lien de parenté.","effects":{"popularite":3,"cohesion":2,"budget":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"L’appel d’offres rouvert séduit trois traiteurs"}],"news":"Food truck : le président annule le marché du beau-frère"},{"tone":"langue-de-bois","label":"Tout a été réalisé dans le respect des règles en vigueur. Une revue interne examinera la procédure, comme il se doit.","effects":{"budget":2,"popularite":-3},"news":"Food truck : le président promet une « revue interne »"},{"tone":"offensive","label":"Dans ce pays, on a le droit d’avoir un beau-frère qui cuisine bien. Ceux qui font des procès d’intention n’ont qu’à goûter.","effects":{"popularite":3,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Une enquête révèle un second contrat pour le même camion"}],"news":"Food truck : le président invite les critiques à « goûter »"}]}]}'),u={pays:e,version:1,textes:s,institutions:n,election:t,lois:a,crises:i,missions:r,presse:o};export{i as crises,u as default,t as election,n as institutions,a as lois,r as missions,e as pays,o as presse,s as textes,l as version};
